// Cache of loaded modules keyed by part number
const _cache: Record<number, any> = {};

async function loadPart(partNum: number): Promise<any> {
  if (_cache[partNum]) return _cache[partNum];
  let mod: any;
  switch(partNum) {
    case 1: mod = await import('./WaveComponents_part1'); break;
    case 2: mod = await import('./WaveComponents_part2'); break;
    case 3: mod = await import('./WaveComponents_part3'); break;
    case 4: mod = await import('./WaveComponents_part4'); break;
    case 5: mod = await import('./WaveComponents_part5'); break;
    case 6: mod = await import('./WaveComponents_part6'); break;
    case 7: mod = await import('./WaveComponents_part7'); break;
    case 8: mod = await import('./WaveComponents_part8'); break;
    case 9: mod = await import('./WaveComponents_part9'); break;
    case 10: mod = await import('./WaveComponents_part10'); break;
    default: return null;
  }
  _cache[partNum] = mod;
  return mod;
}

export function WaveRenderer({ tabId }: { tabId: string }) {
  const [Comp, setComp] = useState<React.ComponentType | null>(null);
  const lastTabId = useRef<string>('');

  useEffect(() => {
    if (!tabId || lastTabId.current === tabId) return;
    lastTabId.current = tabId;
    const partNum = TAB_PART[tabId];
    if (!partNum) { setComp(null); return; }
    loadPart(partNum).then(mod => {
      if (!mod) { setComp(null); return; }
      const C = mod[`ForgeTab_${tabId}`];
      setComp(C ? () => C : null);
    }).catch(() => setComp(null));
  }, [tabId]);

  if (!Comp) return null;
  return React.createElement(Comp);
}
